    log.info(`${Math.round(waitMs / 1000)} 秒后下一轮`);
    await interruptibleSleep(waitMs);
  }
  log.info('已退出常驻循环');
}

async function main() {
  switch (cmd) {
    case 'help':
    case '-h':
    case '--help':
      printHelp();
      break;
    case 'init':
      await cmdInit();
      break;
    case 'probe':
      await cmdProbe();
      break;
    case 'once':
      await cmdOnce(false);
      break;
    case 'dry':
      await cmdOnce(true);
      break;
    case 'start':
      await cmdStart();
      break;
    default:
      log.error('未知命令：', cmd);
      printHelp();
      process.exitCode = 1;
  }
}

main().catch((e) => {
  log.error(e);
  process.exitCode = 1;
});

