# unit test diffOnSale + format
node --input-type=module -e @"
import { diffOnSale, formatChangeLines, alertTemplate, alertTitle } from './src/sellfox/diff.js';

function assert(c, m) { if (!c) { console.error('FAIL', m); process.exitCode = 1; } else console.log('OK', m); }

// 1 first round
let r = diffOnSale(null, { onSaleMap: { a: { name: 'A', parentId: '1' }, b: { name: 'B', parentId: '2' } } });
assert(r.isFirst && r.delistedCount === 0 && r.listedCount === 0 && r.events.length === 0, 'first: no alert');

// 2 delist only
r = diffOnSale(
  { onSaleMap: { a: { name: 'A', parentId: '1' }, b: { name: 'B', parentId: '2' } } },
  { onSaleMap: { a: { name: 'A', parentId: '1' } } }
);
assert(r.delistedCount === 1 && r.listedCount === 0, 'delist 1');
assert(r.events.some(e => e.type === 'delist' && e.items[0].skcId === 'b'), 'delist item b');
assert(alertTemplate(r.events) === 'red', 'template red');

// 3 onshelf only
r = diffOnSale(
  { onSaleMap: { a: { name: 'A', parentId: '1' } } },
  { onSaleMap: { a: { name: 'A', parentId: '1' }, c: { name: 'New', parentId: '9', selectStatus: '12' } } }
);
assert(r.delistedCount === 0 && r.listedCount === 1, 'onshelf 1');
assert(r.events.some(e => e.type === 'onshelf' && e.items[0].skcId === 'c'), 'onshelf item c');
assert(alertTemplate(r.events) === 'green', 'template green');
assert(alertTitle(r.events).includes('上架'), 'title onshelf');
const lines = formatChangeLines('Agnis', r.events.filter(e => e.severity==='alert'), { editBaseUrl: 'https://agentseller.temu.com' });
assert(lines.some(l => l.includes('上架') && l.includes('1')), 'format onshelf line');
assert(lines.some(l => l.includes('productId=9')), 'edit link');

// 4 mixed
r = diffOnSale(
  { onSaleMap: { a: { name: 'A' }, b: { name: 'B' } } },
  { onSaleMap: { a: { name: 'A' }, c: { name: 'C' } } }
);
assert(r.delistedCount === 1 && r.listedCount === 1, 'mixed');
assert(alertTemplate(r.events) === 'orange', 'template orange');

// 5 incomplete skip (10 -> 3)
const big = {};
for (let i = 0; i < 10; i++) big['id'+i] = { name: 'x'+i };
const small = { id0: big.id0, id1: big.id1, id2: big.id2 };
r = diffOnSale({ onSaleMap: big }, { onSaleMap: small });
assert(r.skipUpdate && r.delistedCount === 0 && r.listedCount === 0, 'incomplete skip');
assert(Object.keys(r.nextSnap.onSaleMap).length === 10, 'keep prev baseline');

// 6 no change
r = diffOnSale(
  { onSaleMap: { a: { name: 'A' } } },
  { onSaleMap: { a: { name: 'A' } } }
);
assert(r.events.length === 0 && r.delistedCount === 0 && r.listedCount === 0, 'stable');

console.log(process.exitCode ? 'SOME FAILED' : 'ALL PASSED');
"@
