$ErrorActionPreference = 'Stop'
$src = 'E:\project\temu\temu-monitor'
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$dist = 'E:\project\temu\_dist'
New-Item -ItemType Directory -Force -Path $dist | Out-Null
$outDir = Join-Path $dist ("temu-traffic-local-" + $stamp)
$zipPath = Join-Path $dist ("temu-traffic-local-" + $stamp + ".zip")
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

$excludeDirNames = 'node_modules','.userdata','logs','data','capture','__pycache__','.git'
$excludeFileNames = 'sellfox.config.json','config.json','openapi.config.json'

$files = Get-ChildItem -LiteralPath $src -Recurse -File -Force
$count = 0
foreach ($f in $files) {
  $full = $f.FullName
  if (-not $full.StartsWith($src)) { continue }
  $rel = $full.Substring($src.Length)
  if ($rel.StartsWith('\')) { $rel = $rel.Substring(1) }
  if ($rel.StartsWith('/')) { $rel = $rel.Substring(1) }
  $parts = $rel.Split([char]0x5C)
  $skip = $false
  foreach ($p in $parts) {
    if ($excludeDirNames -contains $p) { $skip = $true; break }
  }
  if ($excludeFileNames -contains $f.Name) { $skip = $true }
  if ($f.Extension -eq '.log') { $skip = $true }
  if ($skip) { continue }
  $dest = Join-Path $outDir $rel
  $parent = Split-Path -Parent $dest
  if (-not (Test-Path -LiteralPath $parent)) {
    New-Item -ItemType Directory -Force -Path $parent | Out-Null
  }
  Copy-Item -LiteralPath $full -Destination $dest -Force
  $count++
}
Write-Host "copied $count files to $outDir"
New-Item -ItemType Directory -Force -Path (Join-Path $outDir 'data') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $outDir 'logs') | Out-Null
[IO.File]::WriteAllText((Join-Path $outDir 'data\.gitkeep'), '')
