$note = "发同事前已剔除私密文件。`r`n见 使用说明.txt`r`n1 copy config.example.json config.json`r`n2 改飞书+店名 fullRun=false`r`n3 npm install`r`n4 npm run login`r`n5 npm run once / start`r`n"
[IO.File]::WriteAllText((Join-Path $outDir '发给同事-先读我.txt'), $note, [Text.UTF8Encoding]::new($false))
if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
Compress-Archive -Path (Join-Path $outDir '*') -DestinationPath $zipPath -Force
Write-Host "ZIP=$zipPath"
Write-Host "SIZE=$((Get-Item -LiteralPath $zipPath).Length)"
Get-ChildItem -LiteralPath $outDir | ForEach-Object { $_.Name }
$leaks = Get-ChildItem -LiteralPath $outDir -Recurse -File | Where-Object { @('config.json','sellfox.config.json','openapi.config.json') -contains $_.Name }
if ($leaks) { 'LEAK'; $leaks | ForEach-Object FullName } else { 'NO_SECRET_FILES' }

